<template>
<section class="history-today" :class="{'history-dark':dark}" aria-labelledby="history-today-title"><header><div><h2 id="history-today-title">历史上的今天</h2><p>{{dateLabel}} · 回看同一天发生的历史事件</p></div><button type="button" @click="expanded=!expanded" :aria-expanded="expanded">{{expanded?'收起':'展开'}}</button></header><template v-if="expanded"><nav class="history-tabs" aria-label="历史事件分类"><button v-for="tab in tabs" :key="tab.key" type="button" :aria-pressed="selected===tab.key" @click="selected=tab.key;showAll=false">{{tab.label}}</button><span role="status">{{status}}</span></nav><p v-if="stale" class="history-warning">当前展示 {{dataDate}} 的历史资料，尚未更新到今日 {{today}}。</p><ol v-if="visible.length" class="history-list"><li v-for="(event,index) in visible" :key="`${selected}-${index}`"><span class="history-year">{{event.year<0?`公元前 ${-event.year}`:event.year}} 年</span><div><p>{{event.text}}</p><a :href="event.url" target="_blank" rel="noopener noreferrer">维基百科原文 ↗</a></div></li></ol><div v-else class="history-empty">{{loading?'正在加载历史资料…':'暂无该分类资料'}}<button v-if="!loading" type="button" @click="load">重试</button></div><div class="history-more"><span>{{items.length}} 条记录 · 按年份倒序</span><button v-if="items.length>6" type="button" @click="showAll=!showAll">{{showAll?'精简列表 ↑':'更多历史事件 ↓'}}</button></div><footer>来源：<a v-if="sourceUrl" :href="sourceUrl" target="_blank" rel="noopener noreferrer">维基百科（中文）日期条目</a> · 摘录遵循 <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a>，详情与修订历史见原文。按中国标准时间每日获取；历史资料可能存在差异，请结合原文与其他史料核实。</footer></template></section>
</template>
<script>
import {chinaDateISO} from '../utils/china-calendar.mjs';
export default{name:'HistoryToday',props:{dark:Boolean},data:()=>({expanded:true,selected:'events',tabs:[{key:'events',label:'历史事件'},{key:'births',label:'人物出生'},{key:'deaths',label:'人物逝世'}],groups:{},today:chinaDateISO(),dataDate:'',sourceUrl:'',showAll:false,error:false,loading:false,controller:null,timer:null}),computed:{items(){return this.groups[this.selected]||[];},visible(){return this.items.slice(0,this.showAll?30:6);},dateLabel(){const d=this.dataDate||this.today;return `${Number(d.slice(5,7))}月${Number(d.slice(8,10))}日`;},stale(){return !!this.dataDate&&this.dataDate!==this.today;},status(){return this.error?'刷新失败 · 显示已有资料':this.dataDate?`资料日期 ${this.dataDate}`:'等待更新';}},mounted(){this.load();this.timer=setInterval(()=>{const next=chinaDateISO();if(next!==this.today){this.today=next;this.load();}},60000);},beforeUnmount(){clearInterval(this.timer);this.controller?.abort();},methods:{accept(data){if(!/^\d{4}-\d{2}-\d{2}$/.test(data?.date)||!data.groups)throw Error('invalid history');const groups={};for(const key of ['events','births','deaths'])groups[key]=(Array.isArray(data.groups[key])?data.groups[key]:[]).filter(e=>Number.isInteger(e.year)&&typeof e.text==='string'&&/^https:\/\/zh\.wikipedia\.org\/wiki\//.test(e.url)).slice(0,30);if(!groups.events.length)throw Error('empty history');this.groups=groups;this.dataDate=data.date;this.sourceUrl=/^https:\/\/zh\.wikipedia\.org\/wiki\//.test(data.sourceUrl)?data.sourceUrl:'';},async load(){this.loading=true;this.error=false;try{const d=JSON.parse(localStorage.getItem('history-today-v1'));if(d)this.accept(d);}catch{/* optional cache */}this.controller=new AbortController();const timeout=setTimeout(()=>this.controller.abort(),15000);try{const r=await fetch(`${process.env.BASE_URL}history-today.json`,{cache:'no-cache',signal:this.controller.signal});if(!r.ok)throw Error('history request failed');const d=await r.json();this.accept(d);try{localStorage.setItem('history-today-v1',JSON.stringify(d));}catch{/* optional storage */}}catch{this.error=true;}finally{clearTimeout(timeout);this.loading=false;}}}};
</script>
<style scoped>
.history-today{--w-text:#26364c;--w-muted:#7b8799;--w-line:rgba(105,128,160,.15);margin:18px 0 24px;padding:20px 24px;border:1px solid var(--w-line);border-radius:18px;background:rgba(255,255,255,.86);color:var(--w-text)}.history-dark{--w-text:#e2e9f4;--w-muted:#95a3b9;--w-line:rgba(145,164,194,.17);background:rgba(24,31,45,.92)}header{display:flex;align-items:center;justify-content:space-between;gap:12px}h2{font-size:15px;margin:0}header p{font-size:12px;color:var(--w-muted);margin:7px 0 0}button{font:inherit;font-size:12px;background:transparent;color:var(--w-text);border:1px solid var(--w-line);border-radius:6px;padding:6px 9px;cursor:pointer}button:hover,button[aria-pressed="true"]{background:var(--ui-accent-soft,rgba(127,145,171,.1))}a:focus-visible,button:focus-visible{outline:2px solid var(--ui-accent,#43898d);outline-offset:2px}.history-tabs{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:18px 0 12px}.history-tabs>span{font-size:10px;color:var(--w-muted);margin-left:auto}.history-list{padding:0;margin:0;list-style:none;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 22px}.history-list li{display:flex;gap:14px;padding:16px 0;border-bottom:1px solid var(--w-line);min-width:0}.history-year{flex:0 0 76px;font-size:14px;font-weight:600;color:var(--ui-accent,#43898d);line-height:1.8}.history-list li>div{min-width:0;flex:1}.history-list p{font-size:12px;line-height:1.8;margin:0 0 7px;overflow-wrap:anywhere}.history-list a{font-size:10px;color:var(--w-muted)}.history-more{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:14px;font-size:10px;color:var(--w-muted)}footer{font-size:10px;color:var(--w-muted);margin-top:16px;line-height:1.8}footer a{color:inherit}.history-warning{padding:10px;font-size:12px;background:rgba(191,139,55,.09);color:#bf8b37;line-height:1.7}.history-empty{padding:24px;font-size:12px;text-align:center;color:var(--w-muted)}@media(max-width:700px){.history-today{padding:18px 16px}.history-list{grid-template-columns:minmax(0,1fr)}.history-year{flex-basis:65px}.history-tabs>span{margin-left:0}}
</style>
